<dialog class="{{ $classes }}" id="{{ $id }}-drawer" aria-labelledby="{{ $id }}-title"@if ($hasDescription) aria-describedby="{{ $id }}-description"@endif data-cm-controller="drawer" data-cm-drawer-state="{{ $open ? 'open' : 'closed' }}" data-cm-drawer-dismissible="{{ $dismissible ? 'true' : 'false' }}"@if ($open) open@endif{!! $attributes !!}><div class="cm-drawer__surface"><header class="cm-drawer__header"><h2 class="cm-drawer__title" id="{{ $id }}-title">{{ $header ?? $title }}</h2>@if ($actions !== null)<div class="cm-drawer__actions">{{ $actions }}</div>@endif<button class="cm-drawer__close" type="button" aria-label="{{ $closeLabel }}" data-cm-drawer-close@if (!$dismissible) disabled@endif>×</button></header>@if ($customDescription)<div class="cm-drawer__description" id="{{ $id }}-description">{{ $descriptionContent }}</div>@elseif ($hasDescription)<p class="cm-drawer__description" id="{{ $id }}-description">{{ $descriptionContent }}</p>@endif<div class="cm-drawer__body">{{ $body }}</div>@if ($footer !== null)<footer class="cm-drawer__footer">{{ $footer }}</footer>@endif</div></dialog>
